package main

import (
	"bufio"
	"os"
	"strconv"
)

type BIT struct {
	n    int
	tree []int
}

func NewBIT(n int) *BIT {
	return &BIT{n: n, tree: make([]int, n+1)}
}

func (b *BIT) Update(i, v int) {
	for ; i <= b.n; i += i & (-i) {
		if b.tree[i] < v {
			b.tree[i] = v
		}
	}
}

func (b *BIT) Query(i int) int {
	res := 0
	for ; i > 0; i -= i & (-i) {
		if b.tree[i] > res {
			res = b.tree[i]
		}
	}
	return res
}

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<20)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	readInt := func() int {
		n := 0
		c, _ := reader.ReadByte()
		for c == ' ' || c == '\n' || c == '\r' {
			c, _ = reader.ReadByte()
		}
		neg := false
		if c == '-' {
			neg = true
			c, _ = reader.ReadByte()
		}
		for c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
			c, _ = reader.ReadByte()
		}
		if neg {
			return -n
		}
		return n
	}

	n := readInt()
	m := readInt()

	diff := make([]int, m+2)
	for i := 0; i < n; i++ {
		l := readInt()
		r := readInt()
		diff[l]++
		diff[r+1]--
	}
	a := make([]int, m+1)
	cur := 0
	for i := 1; i <= m; i++ {
		cur += diff[i]
		a[i] = cur
	}

	maxV := n + 2

	f := make([]int, m+2)
	g := make([]int, m+2)

	bit1 := NewBIT(maxV)
	for i := 1; i <= m; i++ {
		best := bit1.Query(a[i] + 1)
		f[i] = best + 1
		bit1.Update(a[i]+1, f[i])
	}

	bit2 := NewBIT(maxV)
	for i := m; i >= 1; i-- {
		best := bit2.Query(a[i] + 1)
		g[i] = best + 1
		bit2.Update(a[i]+1, g[i])
	}

	ans := 0
	for i := 1; i <= m; i++ {
		if f[i]+g[i]-1 > ans {
			ans = f[i] + g[i] - 1
		}
	}
	writer.WriteString(strconv.Itoa(ans))
	writer.WriteString("\n")
}
