	N := int64(n)
	for k := int64(1); k <= int64(a); k++ {
		q := N / k
		r := N % k
		cost := r*(c1+c2*q*q) + (k-r)*(c1+c2*(q-1)*(q-1))
		if best == -1 || cost < best {
			best = cost
		}
	}
