package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353

func power(a, b int64) int64 {
	a %= MOD
	if a < 0 {
		a += MOD
	}
	res := int64(1)
	for b > 0 {
		if b&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return res
}

func inv(a int64) int64 {
	return power(a, MOD-2)
}

var fact []int64
var invfact []int64

func C(n, k int) int64 {
	if k < 0 || n < 0 || k > n {
		return 0
	}
	return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var p, s, r int
	fmt.Fscan(reader, &p, &s, &r)

	N := s + p + 10
	fact = make([]int64, N)
	invfact = make([]int64, N)
	fact[0] = 1
	for i := 1; i < N; i++ {
		fact[i] = fact[i-1] * int64(i) % MOD
	}
	invfact[N-1] = inv(fact[N-1])
	for i := N - 1; i > 0; i-- {
		invfact[i-1] = invfact[i] * int64(i) % MOD
	}

	invs := make([]int64, p+2)
	for i := 1; i <= p+1; i++ {
		invs[i] = inv(int64(i))
	}

	total := C(s-r+p-1, p-1)

	if s == 0 {
		// all zeros
		fmt.Println(invs[p])
		return
	}

	countLess := func(n, T, m int) int64 {
		// n players each in [0, m-1] summing to T
		if n == 0 {
			if T == 0 {
				return 1
			}
			return 0
		}
		if T < 0 {
			return 0
		}
		var res int64 = 0
		maxJ := n
		if m > 0 {
			if T/m < maxJ {
				maxJ = T / m
			}
		} else {
			maxJ = 0
		}
		for j := 0; j <= maxJ; j++ {
			term := C(n, j) * C(T-j*m+n-1, n-1) % MOD
			if j%2 == 0 {
				res = (res + term) % MOD
			} else {
				res = (res - term + MOD) % MOD
			}
		}
		return res
	}

	var ans int64 = 0
	start := r
	if start < 1 {
		start = 1
	}
	for m := start; m <= s; m++ {
		rem := s - m
		for k := 0; k <= p-1; k++ {
			if k*m > rem {
				break
			}
			n := p - 1 - k
			T := rem - k*m
			w := countLess(n, T, m)
			if w == 0 {
				continue
			}
			ans = (ans + C(p-1, k)*invs[k+1]%MOD*w) % MOD
		}
	}

	ans = ans * inv(total) % MOD
	fmt.Println(ans)
}
