package main

import (
	"bufio"
	"os"
	"strconv"
)

const MOD = 998244353

var reader *bufio.Reader

func readInt() int {
	n := 0
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r') {
		c, err = reader.ReadByte()
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = reader.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, err = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	reader = bufio.NewReaderSize(os.Stdin, 1<<20)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	n := readInt()

	head := make([]int32, n+1)
	for i := 0; i <= n; i++ {
		head[i] = -1
	}
	m := 2 * (n - 1)
	if m < 0 {
		m = 0
	}
	nxt := make([]int32, m)
	to := make([]int32, m)
	cnt := int32(0)
	for i := 0; i < n-1; i++ {
		u := int32(readInt())
		v := int32(readInt())
		to[cnt] = v
		nxt[cnt] = head[u]
		head[u] = cnt
		cnt++
		to[cnt] = u
		nxt[cnt] = head[v]
		head[v] = cnt
		cnt++
	}

	parent := make([]int32, n+1)
	order := make([]int32, 0, n)
	stack := make([]int32, 0, n)
	stack = append(stack, 1)
	parent[1] = 0
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, v)
		for e := head[v]; e != -1; e = nxt[e] {
			u := to[e]
			if u != parent[v] {
				parent[u] = v
				stack = append(stack, u)
			}
		}
	}

	a := make([]int64, n+1)
	b := make([]int64, n+1)
	c := make([]int64, n+1)

	for i := len(order) - 1; i >= 0; i-- {
		v := order[i]
		var P int64 = 1
		var S int64 = 0
		var C int64 = 1
		for e := head[v]; e != -1; e = nxt[e] {
			u := to[e]
			if u == parent[v] {
				continue
			}
			t := (2*a[u] + c[u]) % MOD
			S = (S*t + P*((b[u]+c[u])%MOD)) % MOD
			P = P * t % MOD
			C = C * ((a[u] + c[u]) % MOD) % MOD
		}
		a[v] = S
		c[v] = C
		b[v] = (P - C + MOD) % MOD
	}

	ans := (a[1] + c[1]) % MOD
	writer.WriteString(strconv.FormatInt(ans, 10))
	writer.WriteString("\n")
}
