import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func power(a, b uint64) uint64 {
	a %= MOD
	var r uint64 = 1
	for b > 0 {
		if b&1 == 1 {
			r = r * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return r
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var x, n uint64
	fmt.Fscan(reader, &x, &n)
	primes := []uint64{}
	tmp := x
	for p := uint64(2); p*p <= tmp; p++ {
		if tmp%p == 0 {
			primes = append(primes, p)
			for tmp%p == 0 {
				tmp /= p
			}
		}
	}
	if tmp > 1 {
		primes = append(primes, tmp)
	}
	var ans uint64 = 1
	for _, p := range primes {
		var e uint64 = 0
		cur := p
		for {
			if cur > n {
				break
			}
			e += n / cur
			if cur > n/p {
				break
			}
			cur *= p
		}
		ans = ans * power(p, e) % MOD
	}
	fmt.Println(ans)
}
