package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353

func power(a, b int64) int64 {
	a %= MOD
	if a < 0 {
		a += MOD
	}
	var r int64 = 1
	for b > 0 {
		if b&1 == 1 {
			r = r * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return r
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, k, l int64
	fmt.Fscan(reader, &n, &k, &l)

	N := 2*n + 3
	fact := make([]int64, N+1)
	invfact := make([]int64, N+1)
	fact[0] = 1
	for i := int64(1); i <= N; i++ {
		fact[i] = fact[i-1] * i % MOD
	}
	invfact[N] = power(fact[N], MOD-2)
	for i := N; i >= 1; i-- {
		invfact[i-1] = invfact[i] * i % MOD
	}

	comb := func(a, b int64) int64 {
		if b < 0 || b > a || a < 0 {
			return 0
		}
		return fact[a] * invfact[b] % MOD * invfact[a-b] % MOD
	}

	pow2 := make([]int64, n+1)
	pow2[0] = 1
	for i := int64(1); i <= n; i++ {
		pow2[i] = pow2[i-1] * 2 % MOD
	}

	g := make([]int64, n+1)
	for m := int64(0); m <= n; m++ {
		g[m] = pow2[m] * fact[m] % MOD * fact[m] % MOD * invfact[2*m+1] % MOD
	}

	var ans int64 = 0
	for j := k; j <= n; j++ {
		c := comb(n, j)
		if c == 0 {
			continue
		}
		for i := int64(0); i <= n-j; i++ {
			t := c * comb(n-j, i) % MOD * g[j+i] % MOD
			if i&1 == 1 {
				ans -= t
				if ans < 0 {
					ans += MOD
				}
			} else {
				ans += t
				if ans >= MOD {
					ans -= MOD
				}
			}
		}
	}

	ans = ans * (l % MOD) % MOD
	fmt.Fprintln(writer, ans)
}
