package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	var s string
	fmt.Fscan(reader, &s)
	m := len(s)

	// prefix function
	pi := make([]int, m)
	pi[0] = 0
	for j := 1; j < m; j++ {
		k := pi[j-1]
		for k > 0 && s[j] != s[k] {
			k = pi[k-1]
		}
		if s[j] == s[k] {
			k++
		}
		pi[j] = k
	}

	// automaton delta[j][c] for j in 0..m-1
	delta := make([][2]int, m)
	for j := 0; j < m; j++ {
		for c := 0; c < 2; c++ {
			ch := byte('0' + c)
			if s[j] == ch {
				delta[j][c] = j + 1
			} else if j == 0 {
				delta[j][c] = 0
			} else {
				delta[j][c] = delta[pi[j-1]][c]
			}
		}
	}

	var answer int64 = 0

	for i := 0; i < n; i++ {
		L := i + m - n
		if L < 0 {
			L = 0
		}
		st := 0
		ok := true
		for k := 0; k < L; k++ {
			c := int(s[m-L+k] - '0')
			st = delta[st][c]
			if st == m {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		dp := make([]int64, m)
		dp[st] = 1
		rem := i - L
		for step := 0; step < rem; step++ {
			ndp := make([]int64, m)
			for state := 0; state < m; state++ {
				if dp[state] == 0 {
					continue
				}
				for c := 0; c < 2; c++ {
					ns := delta[state][c]
					if ns != m {
						ndp[ns] += dp[state]
					}
				}
			}
			dp = ndp
		}
		var total int64 = 0
		for state := 0; state < m; state++ {
			if dp[state] == 0 {
				continue
			}
			st2 := state
			good := true
			for k := 0; k < m-1; k++ {
				c := int(s[k] - '0')
				st2 = delta[st2][c]
				if st2 == m {
					good = false
					break
				}
			}
			if good {
				total += dp[state]
			}
		}
		free := n - i - m
		if free < 0 {
			free = 0
		}
		answer += total * (int64(1) << uint(free))
	}

	fmt.Println(answer)
}
