func power(a, b, p int64) int64 {
	a %= p
	var r int64 = 1
	for b > 0 {
		if b&1 == 1 {
			r = r * a % p
		}
		a = a * a % p
		b >>= 1
	}
	return r
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(reader, &a, &b, &p, &x)
	inva := power(a, p-2, p)
	m := p * (p - 1)
	var ans int64 = 0
	cur := b % p
	for i := int64(0); i <= p-2; i++ {
		// c = b * inva^i mod p
		c := cur
		k := ((i-c)%p + p) % p
		n := i + (p-1)*k
		if n == 0 {
			n = m
		}
		if n <= x {
			ans += (x-n)/m + 1
		}
		cur = cur * inva % p
	}
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, ans)
}
