package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF = int64(1) << 60

var sz int

func mul(A, B [][]int64) [][]int64 {
	C := make([][]int64, sz)
	for i := 0; i < sz; i++ {
		C[i] = make([]int64, sz)
		for j := 0; j < sz; j++ {
			C[i][j] = INF
		}
	}
	for i := 0; i < sz; i++ {
		for k := 0; k < sz; k++ {
			if A[i][k] >= INF {
				continue
			}
			aik := A[i][k]
			for j := 0; j < sz; j++ {
				if B[k][j] >= INF {
					continue
				}
				v := aik + B[k][j]
				if v < C[i][j] {
					C[i][j] = v
				}
			}
		}
	}
	return C
}

func identity() [][]int64 {
	I := make([][]int64, sz)
	for i := 0; i < sz; i++ {
		I[i] = make([]int64, sz)
		for j := 0; j < sz; j++ {
			if i == j {
				I[i][j] = 0
			} else {
				I[i][j] = INF
			}
		}
	}
	return I
}

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscan(reader, &n, &m)
	a := make([]int64, n)
	b := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &a[i])
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &b[i])
	}

	sz = n + 1

	M := identity()
	for k := 0; k < n; k++ {
		T := make([][]int64, sz)
		for i := 0; i < sz; i++ {
			T[i] = make([]int64, sz)
			for j := 0; j < sz; j++ {
				T[i][j] = INF
			}
		}
		for i := 0; i < sz; i++ {
			if i+1 < sz {
				if a[k] < T[i][i+1] {
					T[i][i+1] = a[k]
				}
			}
			if i-1 >= 0 {
				if b[k] < T[i][i-1] {
					T[i][i-1] = b[k]
				}
			}
		}
		M = mul(M, T)
	}

	R := identity()
	e := m
	base := M
	for e > 0 {
		if e&1 == 1 {
			R = mul(R, base)
		}
		base = mul(base, base)
		e >>= 1
	}

	fmt.Fprintln(writer, R[0][0])
}
