func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<20)
	writer := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer writer.Flush()

	readInt := func() int {
		n := 0
		c, err := reader.ReadByte()
		for err == nil && (c == ' ' || c == '\n' || c == '\r') {
			c, err = reader.ReadByte()
		}
		neg := false
		if c == '-' {
			neg = true
			c, err = reader.ReadByte()
		}
		for err == nil && c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
			c, err = reader.ReadByte()
		}
		if neg {
			return -n
		}
		return n
	}

	n := readInt()
	m := readInt()
	f := make([]int, n+1)
	for i := 1; i <= n; i++ {
		f[i] = readInt()
	}
	as := make([]int32, m)
	bs := make([]int32, m)
	outCnt := make([]int32, n+2)
	inCnt := make([]int32, n+2)
	for i := 0; i < m; i++ {
		a := readInt()
		b := readInt()
		as[i] = int32(a)
		bs[i] = int32(b)
		outCnt[a]++
		inCnt[b]++
	}
	outStart := make([]int32, n+2)
	inStart := make([]int32, n+2)
	var s1, s2 int32 = 0, 0
	for i := 1; i <= n; i++ {
		outStart[i] = s1
		s1 += outCnt[i]
		inStart[i] = s2
		s2 += inCnt[i]
	}
	outStart[n+1] = s1
	inStart[n+1] = s2
	outPos := make([]int32, n+2)
	inPos := make([]int32, n+2)
	copy(outPos, outStart)
	copy(inPos, inStart)
	outAdj := make([]int32, m)
	inAdj := make([]int32, m)
	for i := 0; i < m; i++ {
		a := as[i]
		b := bs[i]
		outAdj[outPos[a]] = b
		outPos[a]++
		inAdj[inPos[b]] = a
		inPos[b]++
	}

	A := make([]bool, n+1)
	B := make([]bool, n+1)
	queue := make([]int32, 0, n)

	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			A[i] = true
			queue = append(queue, int32(i))
		}
	}
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		for j := outStart[u]; j < outStart[u+1]; j++ {
			v := outAdj[j]
			if f[v] != 1 && !A[v] {
				A[v] = true
				queue = append(queue, v)
			}
		}
	}

	queue = queue[:0]
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			B[i] = true
			queue = append(queue, int32(i))
		}
	}
	for head := 0; head < len(queue); head++ {
		w := queue[head]
		if f[w] == 1 {
			continue
		}
		for j := inStart[w]; j < inStart[w+1]; j++ {
			v := inAdj[j]
			if !B[v] {
				B[v] = true
				queue = append(queue, v)
			}
		}
	}

	for i := 1; i <= n; i++ {
		if A[i] && B[i] {
			writer.WriteString(strconv.Itoa(1))
		} else {
			writer.WriteString(strconv.Itoa(0))
		}
		writer.WriteByte('\n')
	}
}
