package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

var (
	n, k     int
	a        []int32
	adjStart []int32
	adj      []int32
	order    []int32
	par      []int32
	size     []int32
	down     []int32
	up       []int32
)

func check(x int32) bool {
	for i := n - 1; i >= 0; i-- {
		v := order[i]
		if a[v] < x {
			down[v] = 0
			continue
		}
		var sumFull int32 = 0
		var best int32 = 0
		for j := adjStart[v]; j < adjStart[v+1]; j++ {
			u := adj[j]
			if u == par[v] {
				continue
			}
			if down[u] == size[u] {
				sumFull += size[u]
			} else if down[u] > best {
				best = down[u]
			}
		}
		down[v] = 1 + sumFull + best
	}
	kk := int32(k)
	for i := 0; i < n; i++ {
		v := order[i]
		if a[v] < x {
			for j := adjStart[v]; j < adjStart[v+1]; j++ {
				u := adj[j]
				if u == par[v] {
					continue
				}
				up[u] = 0
			}
			continue
		}
		var sumFull int32 = 0
		var b1, b2 int32 = 0, 0
		var b1Idx int32 = -1
		for j := adjStart[v]; j < adjStart[v+1]; j++ {
			u := adj[j]
			if u == par[v] {
				continue
			}
			sz := size[u]
			dp := down[u]
			if dp == sz {
				sumFull += sz
			} else if dp > b1 {
				b2 = b1
				b1 = dp
				b1Idx = u
			} else if dp > b2 {
				b2 = dp
			}
		}
		if v != order[0] {
			sz := int32(n) - size[v]
			dp := up[v]
			if dp == sz {
				sumFull += sz
			} else if dp > b1 {
				b2 = b1
				b1 = dp
				b1Idx = -2
			} else if dp > b2 {
				b2 = dp
			}
		}
		total := 1 + sumFull + b1
		if total >= kk {
			return true
		}
		for j := adjStart[v]; j < adjStart[v+1]; j++ {
			c := adj[j]
			if c == par[v] {
				continue
			}
			s := sumFull
			bb := b1
			if down[c] == size[c] {
				s -= size[c]
			} else if c == b1Idx {
				bb = b2
			}
			up[c] = 1 + s + bb
		}
	}
	return false
}

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<20)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	readInt := func() int {
		nn := 0
		c, err := reader.ReadByte()
		for err == nil && (c == ' ' || c == '\n' || c == '\r') {
			c, err = reader.ReadByte()
		}
		neg := false
		if c == '-' {
			neg = true
			c, err = reader.ReadByte()
		}
		for err == nil && c >= '0' && c <= '9' {
			nn = nn*10 + int(c-'0')
			c, err = reader.ReadByte()
		}
		if neg {
			return -nn
		}
		return nn
	}

	n = readInt()
	k = readInt()
	a = make([]int32, n+1)
	for i := 1; i <= n; i++ {
		a[i] = int32(readInt())
	}
	us := make([]int32, n-1)
	vs := make([]int32, n-1)
	deg := make([]int32, n+2)
	for i := 0; i < n-1; i++ {
		u := int32(readInt())
		v := int32(readInt())
		us[i] = u
		vs[i] = v
		deg[u]++
		deg[v]++
	}
	adjStart = make([]int32, n+2)
	for i := 1; i <= n; i++ {
		adjStart[i+1] = adjStart[i] + deg[i]
	}
	pos := make([]int32, n+2)
	copy(pos, adjStart)
	adj = make([]int32, 2*(n-1))
	for i := 0; i < n-1; i++ {
		u := us[i]
		v := vs[i]
		adj[pos[u]] = v
		pos[u]++
		adj[pos[v]] = u
		pos[v]++
	}
	order = make([]int32, n)
	par = make([]int32, n+1)
	size = make([]int32, n+1)
	down = make([]int32, n+1)
	up = make([]int32, n+1)

	order[0] = 1
	par[1] = 0
	cnt := 1
	head := 0
	for head < cnt {
		v := order[head]
		head++
		for j := adjStart[v]; j < adjStart[v+1]; j++ {
			u := adj[j]
			if u == par[v] {
				continue
			}
			par[u] = v
			order[cnt] = u
			cnt++
		}
	}
	for i := 1; i <= n; i++ {
		size[i] = 1
	}
	for i := n - 1; i >= 1; i-- {
		v := order[i]
		size[par[v]] += size[v]
	}

	vals := make([]int32, n)
	for i := 1; i <= n; i++ {
		vals[i-1] = a[i]
	}
	sort.Slice(vals, func(i, j int) bool { return vals[i] < vals[j] })
	// unique
	m := 0
	for i := 0; i < n; i++ {
		if i == 0 || vals[i] != vals[i-1] {
			vals[m] = vals[i]
			m++
		}
	}
	vals = vals[:m]

	lo, hi := 0, m-1
	ans := vals[0]
	for lo <= hi {
		mid := (lo + hi) / 2
		if check(vals[mid]) {
			ans = vals[mid]
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}
	writer.WriteString(strconv.Itoa(int(ans)))
	writer.WriteString("\n")
}
