import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(reader, &n, &k)

	// inverses
	inv := make([]int64, n+2)
	if n+1 >= 1 {
		inv[1] = 1
	}
	for i := 2; i <= n+1; i++ {
		inv[i] = (MOD - (MOD/int64(i))*inv[MOD%int64(i)]%MOD) % MOD
	}

	q := make([]int64, n)
	q[0] = 1
	var S int64 = 0
	for m := 1; m <= n-1; m++ {
		S = (S + q[m-1]) % MOD
		if m-k > 0 {
			S = (S - q[m-k-1]) % MOD
			if S < 0 {
				S += MOD
			}
		}
		q[m] = S * inv[m] % MOD
	}

	var total int64 = 0
	for m := 0; m <= n-1; m++ {
		total = (total + q[m]) % MOD
	}

	var factNm1 int64 = 1
	for i := 2; i <= n-1; i++ {
		factNm1 = factNm1 * int64(i) % MOD
	}
	factN := factNm1 * int64(n) % MOD

	ans := (factN - factNm1*total%MOD) % MOD
	if ans < 0 {
		ans += MOD
	}
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, ans)
}
