package main

import (
	"bufio"
	"fmt"
	"os"
)

var n int64

type mat [6][6]int64

func mul(a, b mat) mat {
	var c mat
	for i := 0; i < 6; i++ {
		for j := 0; j < 6; j++ {
			var s int64 = 0
			for k := 0; k < 6; k++ {
				s = (s + a[i][k]*b[k][j]%n) % n
			}
			c[i][j] = s
		}
	}
	return c
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var sx, sy, dx, dy, t int64
	fmt.Fscan(reader, &n, &sx, &sy, &dx, &dy, &t)

	X := (sx - 1) % n
	Y := (sy - 1) % n
	DX := ((dx % n) + n) % n
	DY := ((dy % n) + n) % n

	var m mat
	// order: X, Y, dx, dy, t, 1
	m[0] = [6]int64{2, 1, 1, 0, 1, 2}
	m[1] = [6]int64{1, 2, 0, 1, 1, 2}
	m[2] = [6]int64{1, 1, 1, 0, 1, 2}
	m[3] = [6]int64{1, 1, 0, 1, 1, 2}
	m[4] = [6]int64{0, 0, 0, 0, 1, 1}
	m[5] = [6]int64{0, 0, 0, 0, 0, 1}
	for i := 0; i < 6; i++ {
		for j := 0; j < 6; j++ {
			m[i][j] %= n
		}
	}

	var res mat
	for i := 0; i < 6; i++ {
		res[i][i] = 1 % n
	}

	e := t
	for e > 0 {
		if e&1 == 1 {
			res = mul(res, m)
		}
		m = mul(m, m)
		e >>= 1
	}

	v := [6]int64{X % n, Y % n, DX, DY, 0, 1 % n}
	var out [6]int64
	for i := 0; i < 6; i++ {
		var s int64 = 0
		for k := 0; k < 6; k++ {
			s = (s + res[i][k]*v[k]%n) % n
		}
		out[i] = s
	}

	fmt.Printf("%d %d\n", out[0]+1, out[1]+1)
}
