package main

import (
	"fmt"
)

const MOD = 1000000007

func main() {
	var n, x, pos int
	fmt.Scan(&n, &x, &pos)
	cl, cg := 0, 0
	left, right := 0, n
	for left < right {
		mid := (left + right) / 2
		if mid == pos {
			left = mid + 1
		} else if mid < pos {
			cl++
			left = mid + 1
		} else {
			cg++
			right = mid
		}
	}
	availLess := x - 1
	availGreater := n - x
	if cl > availLess || cg > availGreater {
		fmt.Println(0)
		return
	}
	res := int64(1)
	for i := 0; i < cl; i++ {
		res = res * int64(availLess-i) % MOD
	}
	for i := 0; i < cg; i++ {
		res = res * int64(availGreater-i) % MOD
	}
	rem := n - 1 - cl - cg
	for i := 1; i <= rem; i++ {
		res = res * int64(i) % MOD
	}
	fmt.Println(res)
}
