		var nd [5][5][12][12]int64
		for a := 1; a <= 4; a++ {
			for b := 1; b <= 4; b++ {
				for h := 0; h <= 11; h++ {
					for v := 0; v <= 11; v++ {
						cnt := dp[a][b][h][v]
						if cnt == 0 {
							continue
						}
						for c := 1; c <= 4; c++ {
							if c == b {
								continue
							}
							nh, nv := h, v
							if a < b && b > c {
								nh++
							}
							if a > b && b < c {
								nv++
							}
							if nh > 11 || nv > 11 {
								continue
							}
							nd[b][c][nh][nv] += cnt
						}
					}
				}
			}
		}
		dp = nd
	}
	var res int64
	if t >= 1 && t <= 11 && t-1 >= 0 && t-1 <= 11 {
		for a := 1; a <= 4; a++ {
