package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func gen(a []int64, m int64) []int64 {
	n := len(a)
	res := make([]int64, 0, 1<<uint(n))
	total := 1 << uint(n)
	for mask := 0; mask < total; mask++ {
		var s int64 = 0
		for i := 0; i < n; i++ {
			if mask&(1<<uint(i)) != 0 {
				s += a[i]
				if s >= m {
					s -= m
				}
			}
		}
		res = append(res, s%m)
	}
	return res
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n int
	var m int64
	fmt.Fscan(reader, &n, &m)
	a := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &a[i])
		a[i] %= m
	}

	half := n / 2
	A := gen(a[:half], m)
	B := gen(a[half:], m)

	sort.Slice(B, func(i, j int) bool { return B[i] < B[j] })

	var best int64 = 0
	lb := len(B)
	maxB := B[lb-1]
	for _, x := range A {
		// find largest y with y <= m-1-x
		target := m - 1 - x
		idx := sort.Search(lb, func(i int) bool { return B[i] > target })
		if idx > 0 {
			v := x + B[idx-1]
			if v > best {
				best = v
			}
		}
		v2 := x + maxB
		if v2 >= m {
			v2 -= m
		}
		if v2 > best {
			best = v2
		}
	}

	fmt.Fprintln(writer, best)
}
