package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	if m > n {
		n, m = m, n
	}
	full := (1 << uint(m)) - 1
	const INF = 1 << 29

	spread := func(mask int) int {
		return (mask | (mask << 1) | (mask >> 1)) & full
	}

	size := 1 << uint(m)
	dp := make([][]int, size)
	ndp := make([][]int, size)
	for i := 0; i < size; i++ {
		dp[i] = make([]int, size)
		ndp[i] = make([]int, size)
		for j := 0; j < size; j++ {
			dp[i][j] = INF
		}
	}

	for c := 0; c < size; c++ {
		s := spread(c)
		p := bits.OnesCount(uint(c))
		if p < dp[c][s] {
			dp[c][s] = p
		}
	}

	for i := 1; i < n; i++ {
		for a := 0; a < size; a++ {
			for b := 0; b < size; b++ {
				ndp[a][b] = INF
			}
		}
		for c := 0; c < size; c++ {
			for cov := 0; cov < size; cov++ {
				cur := dp[c][cov]
				if cur >= INF {
					continue
				}
				for d := 0; d < size; d++ {
					if (cov|d)&full != full {
						continue
					}
					ncov := spread(d) | c
					val := cur + bits.OnesCount(uint(d))
					if val < ndp[d][ncov] {
						ndp[d][ncov] = val
					}
				}
			}
		}
		dp, ndp = ndp, dp
	}

	best := INF
	for c := 0; c < size; c++ {
		if dp[c][full] < best {
			best = dp[c][full]
		}
	}

	fmt.Println(n*m - best)
}
